/*
 * A070187  Primes p such that x^11 = 2 has a solution mod p, but x^(11^2) = 2
 *          has no solution mod p.
 * https://oeis.org/A070187
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = the n-th prime p such that x¹¹ ≡ 2 (mod p) has a solution
 *            but x¹²¹ ≡ 2 (mod p) does not. The sequence is generated by a
 *            search over successive primes
 * Range:     u8 none, u16 n <= 5, u32 n <= 38, u64 n <= 38, u128 n <= 38,
 *            big any n
 * Helpers:   mod_pow, next_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Standard headers */
#include <stdbool.h>
#include <stdlib.h>
#include <stdint.h>
/* Utility headers supplied by the build system */
#include "../utils/next_prime.h"   /* uint64_t next_prime(uint64_t) */
#include "../utils/mod_pow.h"      /* seq_t mod_pow(seq_t base, uint64_t exp, seq_t mod) */

/* Static cache of found primes, sufficient for n up to about 10 000. */
static seq_t term_cache[20000];
static size_t term_len = 0;

/* Last prime examined by the generator.  Starts at 0. */
static uint64_t last_checked_prime = 0;

/* Return the n‑th term (1‑indexed).  If n == 0 return 0 to satisfy
   the compiler.  Calls in any order are O(1) after the required
   primes have been generated. */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;   /* value unused for offset 1 */

    /* Generate primes until we have the required number of terms. */
    while (term_len < (size_t)n) {
        uint64_t p = next_prime(last_checked_prime + 1);
        last_checked_prime = p;

        /* We only need primes p ≡ 1 (mod 121). */
        if ((p % 121ULL) != 1ULL)
            continue;

        /* Exponents for the modular equations. */
        uint64_t e1 = (p - 1ULL) / 11ULL;   /* (p‑1)/11   */
        uint64_t e2 = (p - 1ULL) / 121ULL;  /* (p‑1)/121  */

        /* Condition 1: 2^e1 ≡ 1 (mod p)  -> x¹¹ ≡ 2 possible. */
        if (mod_pow((seq_t)2, e1, (seq_t)p) != (seq_t)1)
            continue;

        /* Condition 2: 2^e2 ≠ 1 (mod p)  -> x¹²¹ ≡ 2 impossible. */
        if (mod_pow((seq_t)2, e2, (seq_t)p) == (seq_t)1)
            continue;

        /* p satisfies both conditions; store it. */
        term_cache[term_len++] = (seq_t)p;
    }

    return term_cache[(size_t)n - 1];
}
